// AR Furniture Designer - builds every screen as a Figma frame and links them as a clickable prototype.
const IMG = { floor: "", home: "" };
const SVG = {"chair": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 150\"><ellipse cx=\"50\" cy=\"143\" rx=\"38\" ry=\"6\" fill=\"#000\" opacity=\".25\"/><rect x=\"14\" y=\"92\" width=\"9\" height=\"50\" rx=\"2\" fill=\"#5e4a3c\"/><rect x=\"77\" y=\"92\" width=\"9\" height=\"50\" rx=\"2\" fill=\"#5e4a3c\"/><rect x=\"30\" y=\"4\" width=\"40\" height=\"76\" rx=\"5\" fill=\"#8a6f5d\"/><rect x=\"38\" y=\"12\" width=\"24\" height=\"42\" rx=\"3\" fill=\"#4a3a30\"/><path d=\"M50 60c6-4 8 2 3 5\" stroke=\"#d8c6b8\" stroke-width=\"2\" fill=\"none\"/><rect x=\"6\" y=\"58\" width=\"16\" height=\"9\" rx=\"2\" fill=\"#7b6250\"/><rect x=\"78\" y=\"58\" width=\"16\" height=\"9\" rx=\"2\" fill=\"#7b6250\"/><polygon points=\"16,78 84,78 94,94 6,94\" fill=\"#a98b74\"/></svg>", "couch": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 180 100\"><ellipse cx=\"90\" cy=\"95\" rx=\"84\" ry=\"6\" fill=\"#000\" opacity=\".25\"/><rect x=\"26\" y=\"8\" width=\"128\" height=\"48\" rx=\"14\" fill=\"#4f6c7d\"/><rect x=\"10\" y=\"44\" width=\"160\" height=\"34\" rx=\"10\" fill=\"#6f8fa1\"/><path d=\"M90 46v30\" stroke=\"#4f6c7d\" stroke-width=\"2\"/><rect x=\"0\" y=\"30\" width=\"26\" height=\"52\" rx=\"11\" fill=\"#58798b\"/><rect x=\"154\" y=\"30\" width=\"26\" height=\"52\" rx=\"11\" fill=\"#58798b\"/><rect x=\"18\" y=\"80\" width=\"9\" height=\"12\" fill=\"#3a2a20\"/><rect x=\"153\" y=\"80\" width=\"9\" height=\"12\" fill=\"#3a2a20\"/></svg>", "table": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 140 100\"><ellipse cx=\"70\" cy=\"95\" rx=\"58\" ry=\"5\" fill=\"#000\" opacity=\".25\"/><rect x=\"16\" y=\"34\" width=\"8\" height=\"58\" fill=\"#8a5d36\"/><rect x=\"116\" y=\"34\" width=\"8\" height=\"58\" fill=\"#8a5d36\"/><polygon points=\"22,8 118,8 134,24 6,24\" fill=\"#d6a874\"/><rect x=\"6\" y=\"24\" width=\"128\" height=\"12\" rx=\"3\" fill=\"#b98a5a\"/></svg>", "closet": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 120 140\"><ellipse cx=\"60\" cy=\"136\" rx=\"58\" ry=\"5\" fill=\"#000\" opacity=\".25\"/><polygon points=\"8,16 112,16 120,28 0,28\" fill=\"#98473a\"/><rect x=\"3\" y=\"28\" width=\"114\" height=\"96\" fill=\"#5e2a20\"/><rect x=\"11\" y=\"35\" width=\"98\" height=\"40\" rx=\"3\" fill=\"#7a3526\" stroke=\"#3d1a14\" stroke-width=\"2\"/><rect x=\"11\" y=\"80\" width=\"98\" height=\"38\" rx=\"3\" fill=\"#7a3526\" stroke=\"#3d1a14\" stroke-width=\"2\"/><rect x=\"42\" y=\"52\" width=\"36\" height=\"5\" rx=\"2.5\" fill=\"#cfd4d9\"/><rect x=\"42\" y=\"96\" width=\"36\" height=\"5\" rx=\"2.5\" fill=\"#cfd4d9\"/><rect x=\"0\" y=\"124\" width=\"120\" height=\"10\" rx=\"2\" fill=\"#3d1a14\"/></svg>"};
const NAMES = { chair: "Chair", couch: "Couch", table: "Table", closet: "Closet" };
const TW = { chair: 93, couch: 191, table: 144, closet: 124 };
const KINDS = ["chair", "couch", "table", "closet"];
const W = 390, H = 800, GAP = 90;
const C = { teal: "#0E8A9C", cy: "#2FD6E6", gold: "#EFC65E", navy: "#081E2A", white: "#FFFFFF", ink: "#3A2A05" };
const rgb = h => ({ r: parseInt(h.slice(1, 3), 16) / 255, g: parseInt(h.slice(3, 5), 16) / 255, b: parseInt(h.slice(5, 7), 16) / 255 });
const solid = (h, o = 1) => [{ type: "SOLID", color: rgb(h), opacity: o }];
const imgCache = {};
const img = k => imgCache[k] || (imgCache[k] = [{ type: "IMAGE", scaleMode: "FILL", imageHash: figma.createImage(figma.base64Decode(IMG[k])).hash }]);
const reactions = new Map();
const link = (src, dest, trigger = { type: "ON_CLICK" }) => {
  if (!reactions.has(src)) reactions.set(src, []);
  reactions.get(src).push({ src, dest, trigger });
};

function rect(p, x, y, w, h, fills, r = 0, name = "Rectangle") {
  const n = figma.createRectangle(); n.name = name; n.resize(w, h); n.x = x; n.y = y;
  n.fills = fills; n.cornerRadius = r; p.appendChild(n); return n;
}
function oval(p, x, y, w, h, fills, stroke, name = "Ellipse") {
  const n = figma.createEllipse(); n.name = name; n.resize(w, h); n.x = x; n.y = y; n.fills = fills;
  if (stroke) { n.strokes = solid(stroke.c, stroke.o || 1); n.strokeWeight = stroke.w || 2; }
  p.appendChild(n); return n;
}
function text(p, s, x, y, w, size, bold, color, align = "LEFT", name) {
  const t = figma.createText();
  t.fontName = { family: "Inter", style: bold ? "Bold" : "Regular" };
  t.fontSize = size; t.characters = s; t.fills = solid(color); t.textAlignHorizontal = align;
  t.resize(w, t.height); t.textAutoResize = "HEIGHT"; t.x = x; t.y = y; t.name = name || s;
  p.appendChild(t); return t;
}
function btn(p, label, x, y, w, h, kind, name) {
  const f = figma.createFrame(); f.name = name || label; f.resize(w, h); f.x = x; f.y = y; f.cornerRadius = h / 2;
  f.clipsContent = false;
  if (kind === "gold") f.fills = solid(C.gold);
  else { f.fills = solid(C.white, 0.16); f.strokes = solid(C.white, 0.4); f.strokeWeight = 1; }
  const t = text(f, label, 0, 0, w, kind === "gold" ? 17 : 15, true, kind === "gold" ? C.ink : C.white, "CENTER");
  t.y = (h - t.height) / 2; p.appendChild(f); return f;
}
function pill(p, label, x, y, w, name) {
  const f = figma.createFrame(); f.name = name; f.resize(w, 40); f.x = x; f.y = y; f.cornerRadius = 20;
  f.fills = solid(C.navy, 0.62); f.strokes = solid(C.white, 0.4); f.strokeWeight = 1; f.clipsContent = false;
  const t = text(f, label, 0, 0, w, 14, true, C.white, "CENTER"); t.y = (40 - t.height) / 2; p.appendChild(f); return f;
}
function hint(p, s) {
  const f = figma.createFrame(); f.name = "Hint"; f.cornerRadius = 16; f.fills = solid(C.navy, 0.76); f.clipsContent = false;
  const t = text(f, s, 15, 10, 270, 14, true, C.white, "CENTER");
  f.resize(300, t.height + 20); f.x = 45; f.y = 104; p.appendChild(f); return f;
}
function svgNode(k, targetW) {
  const n = figma.createNodeFromSvg(SVG[k]); n.name = NAMES[k]; n.rescale(targetW / n.width); return n;
}
function frame(name, col, row) {
  const f = figma.createFrame(); f.name = name; f.resize(W, H); f.x = col * (W + GAP); f.y = row * (H + 120);
  f.cornerRadius = 24; f.clipsContent = true; f.fills = solid("#000000"); figma.currentPage.appendChild(f); return f;
}
function arBase(name, col, row, withTop = true) {
  const f = frame(name, col, row); rect(f, 0, 0, W, H, img("floor"), 0, "Camera floor");
  let bar = null;
  if (withTop) { bar = { back: pill(f, "←", 14, 50, 40, "Back"), reset: pill(f, "Reset", 292, 50, 84, "Reset") }; }
  return { f, bar };
}
function plane(f) {
  const v = figma.createVector(); v.name = "Detected floor";
  v.vectorPaths = [{ windingRule: "NONZERO", data: "M 24 300 L 366 262 L 390 700 L 0 740 Z" }];
  v.fills = solid(C.cy, 0.13); v.strokes = solid(C.cy); v.strokeWeight = 2.5; f.appendChild(v); return v;
}
function tray(f, active, backdrop = true) {
  if (backdrop) rect(f, 0, 640, W, 160, solid(C.navy, 0.85), 0, "Tray backdrop");
  const cards = {};
  KINDS.forEach((k, i) => {
    const c = figma.createFrame(); c.name = NAMES[k]; c.resize(84, 70); c.x = 14 + i * 92; c.y = 704; c.cornerRadius = 16;
    c.clipsContent = false; c.fills = k === active ? solid(C.cy) : solid(C.white, 0.12);
    c.strokes = solid(C.white, 0.25); c.strokeWeight = 1.5;
    const n = svgNode(k, 40); const s = Math.min(46 / n.width, 34 / n.height); n.rescale(s);
    n.x = (84 - n.width) / 2; n.y = 6 + (34 - n.height) / 2; c.appendChild(n);
    text(c, NAMES[k], 0, 46, 84, 12, true, k === active ? "#06323A" : C.white, "CENTER");
    f.appendChild(c); cards[k] = c;
  });
  return cards;
}
function ctrl(f, glyph, label, x, big) {
  const c = figma.createFrame(); c.name = label; c.resize(60, 76); c.x = x; c.y = 592; c.fills = []; c.clipsContent = false;
  const d = big ? 62 : 46, oy = big ? 0 : 8;
  const o = oval(c, (60 - d) / 2, oy, d, d, big ? solid(C.white) : solid(C.white, 0.16), big ? null : { c: C.white, o: 0.3, w: 1 }, "Button");
  const g = text(c, glyph, 0, 0, 60, big ? 22 : 22, true, big ? C.navy : C.white, "CENTER"); g.y = oy + (d - g.height) / 2;
  text(c, label, 0, big ? 66 : 58, 60, 11, true, C.white, "CENTER");
  f.appendChild(c); return c;
}

async function main() {
  await figma.loadFontAsync({ family: "Inter", style: "Regular" });
  await figma.loadFontAsync({ family: "Inter", style: "Bold" });

  // 1 Home
  const home = frame("1 · Home", 0, 0);
  rect(home, 0, 0, W, H, img("home"), 0, "Background"); rect(home, 0, 0, W, H, solid(C.navy, 0.62), 0, "Shade");
  rect(home, 26, 430, 58, 58, solid(C.teal), 18, "Logo"); text(home, "AR", 26, 447, 58, 22, true, C.white, "CENTER");
  text(home, "AR Furniture Designer", 26, 500, 330, 36, true, C.white);
  text(home, "Place furniture in your own room and see how it fits before you buy.", 26, 596, 290, 16, false, "#CFE3E8");
  const start = btn(home, "Start AR", 26, 650, 338, 54, "gold");
  const how = btn(home, "How it works", 26, 716, 338, 46, "ghost");

  // 2 How it works
  const hw = frame("2 · How it works", 1, 0);
  rect(hw, 0, 0, W, H, img("home"), 0, "Background"); rect(hw, 0, 0, W, H, solid(C.navy, 0.62), 0, "Shade");
  rect(hw, 0, 430, W, 400, solid("#0F3140"), 28, "Sheet");
  text(hw, "How it works", 24, 454, 340, 22, true, C.white);
  ["Scan the floor until it is detected.", "Choose a piece of furniture.", "Tap the floor to place it.", "Tap it to rotate, resize, move or remove."].forEach((s, i) => {
    const y = 506 + i * 46; oval(hw, 24, y, 28, 28, solid(C.teal), null, "Step " + (i + 1));
    text(hw, String(i + 1), 24, y + 6, 28, 14, true, C.white, "CENTER"); text(hw, s, 64, y + 5, 300, 15, false, "#DBEAEE");
  });
  const gotIt = btn(hw, "Got it", 26, 700, 338, 54, "gold");

  // 3 Scan idle
  const a = arBase("3 · Scan floor", 2, 0); hint(a.f, "Point your phone at the floor, then tap the button below.");
  const scanBtn = btn(a.f, "Tap to scan the floor", 65, 700, 260, 54, "gold", "Scan button");

  // 4 Scanning
  const b = arBase("4 · Scanning", 3, 0); hint(b.f, "Scanning… move your phone slowly over the floor.");
  [330, 372, 422, 484, 560, 650].forEach((y, i) => rect(b.f, 0, y, W, 2, solid(C.cy, 0.55), 0, "Grid line " + (i + 1)));
  rect(b.f, 0, 478, W, 4, solid(C.cy), 0, "Scan sweep");

  // 5 Floor detected
  const c = arBase("5 · Floor detected", 4, 0); plane(c.f); oval(c.f, 135, 498, 120, 44, [], { c: C.cy, w: 3 }, "Placement ring");
  hint(c.f, "Floor detected. Choose a piece of furniture."); const cCards = tray(c.f, null);

  // 6 Placed + 7 Screenshot, one per furniture
  const placed = {}, shot = {};
  KINDS.forEach((k, i) => {
    const p = arBase(`6${"abcd"[i]} · ${NAMES[k]} placed`, i, 1); plane(p.f);
    hint(p.f, `${NAMES[k]} placed. Drag to move it, or tap Capture.`);
    rect(p.f, 0, 585, W, 215, solid(C.navy, 0.85), 0, "Panel backdrop");
    const fw = TW[k] * 1.1, fn = svgNode(k, fw); fn.x = 195 - fw / 2; fn.y = 560 - fn.height; p.f.appendChild(fn);
    oval(p.f, 195 - fw * 0.58, 552, fw * 1.16, 16, [], { c: C.cy, w: 2.5 }, "Selected");
    ctrl(p.f, "⟲", "Rotate", 20, false); ctrl(p.f, "−", "Smaller", 92, false); ctrl(p.f, "+", "Larger", 164, false);
    const del = ctrl(p.f, "✕", "Remove", 236, false); const cap = ctrl(p.f, "◉", "Capture", 308, true);
    p.cards = tray(p.f, k, false); p.del = del; p.cap = cap; placed[k] = p;

    const s = frame(`7${"abcd"[i]} · Screenshot saved (${NAMES[k]})`, i, 2);
    rect(s, 0, 0, W, H, solid("#061821"), 0, "Background");
    text(s, "Screenshot saved", 0, 96, W, 24, true, C.white, "CENTER"); text(s, "Your room with the new furniture.", 0, 132, W, 15, false, "#B9D0D7", "CENTER");
    const pv = figma.createFrame(); pv.name = "Screenshot preview"; pv.resize(216, 444); pv.x = 87; pv.y = 180; pv.cornerRadius = 20; pv.clipsContent = true;
    pv.strokes = solid(C.white); pv.strokeWeight = 3; pv.fills = solid("#000000"); s.appendChild(pv);
    rect(pv, 0, 0, 216, 444, img("floor"), 0, "Photo");
    const sw = fw * 0.554, sn = svgNode(k, sw); sn.x = 108 - sw / 2; sn.y = 310 - sn.height; pv.appendChild(sn);
    const keep = btn(s, "Keep designing", 65, 656, 260, 50, "gold"); const toStart = btn(s, "Back to start", 65, 720, 260, 46, "ghost");
    shot[k] = { f: s };
    link(cap, s); link(keep, p.f); link(toStart, home);
    link(p.bar.back, home); link(p.bar.reset, c.f); link(del, c.f);
  });

  // remaining links
  link(start, a.f); link(how, hw); link(gotIt, home); link(a.bar.back, home); link(b.bar.back, home); link(c.bar.back, home);
  link(scanBtn, b.f); link(b.f, c.f, { type: "AFTER_TIMEOUT", timeout: 2.4 }); link(b.f, c.f);
  link(a.bar.reset, a.f); link(b.bar.reset, b.f); link(c.bar.reset, c.f);
  KINDS.forEach(k => { link(cCards[k], placed[k].f); KINDS.forEach(j => link(placed[k].cards[j], placed[j].f)); });

  for (const [src, list] of reactions) {
    await src.setReactionsAsync(list.map(l => ({
      trigger: l.trigger,
      actions: [{ type: "NODE", destinationId: l.dest.id, navigation: "NAVIGATE", transition: { type: "DISSOLVE", easing: { type: "EASE_OUT" }, duration: 0.25 }, preserveScrollPosition: false }]
    })));
  }
  try { figma.currentPage.flowStartingPoints = [{ nodeId: home.id, name: "Start AR" }]; }
  catch (e) { try { await figma.currentPage.setFlowStartingPointsAsync([{ nodeId: home.id, name: "Start AR" }]); } catch (e2) {} }

  const all = figma.currentPage.children.filter(n => n.type === "FRAME");
  figma.currentPage.selection = all; figma.viewport.scrollAndZoomIntoView(all);
  figma.closePlugin("AR Furniture Designer created. Select the first frame and press Present (▶).");
}
main().catch(e => figma.closePlugin("Error: " + e.message));
